"code": "ACT11", "name": "Superman Activation Series", "video_id": "nDrQyHNwtRg", "video_url": "https://www.youtube.com/shorts/nDrQyHNwtRg", "category_slug": "act", "categories": ["act"], "coaching_cues": "", "admin_notes": "Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied. Preserve as one series; demonstrated movement order has not been verified.", "display_order": 1017}, {"ordinal": 18, "code": "ACT12", "name": "Glute Bridge Activation Series", "video_id": "TYSVGbdo-lI", "video_url": "https://www.youtube.com/shorts/TYSVGbdo-lI", "category_slug": "act", "categories": ["act", "str"], "coaching_cues": "", "admin_notes": "Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied. Preserve as one series; demonstrated movement order has not been verified.", "display_order": 1018}, {"ordinal": 19, "code": "MOB10", "name": "Body Circles Mobility Series", "video_id": "BeWvd3n4lk0", "video_url": "https://www.youtube.com/shorts/BeWvd3n4lk0", "category_slug": "mob", "categories": ["mob"], "coaching_cues": "", "admin_notes": "Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied. Preserve as one series; demonstrated movement order has not been verified.", "display_order": 1019}, {"ordinal": 20, "code": "MOB11", "name": "Ground Mobility Series", "video_id": "wm0LZwdtImk", "video_url": "https://www.youtube.com/shorts/wm0LZwdtImk", "category_slug": "mob", "categories": ["mob"], "coaching_cues": "", "admin_notes": "Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied. Preserve as one series; demonstrated movement order has not been verified.", "display_order": 1020}]$inventory$::jsonb;
  row_data jsonb;
  prior public.exercises%ROWTYPE;
  old_exercises jsonb;
  old_programmes jsonb;
  new_programmes jsonb;
  matched integer;
BEGIN
  LOCK TABLE public.exercises IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.programmes,public.programme_weeks,public.training_days,public.session_blocks,public.saved_blocks,public.saved_block_items,public.athlete_overrides,public.cohort_overrides IN SHARE MODE;
  SELECT coalesce(jsonb_object_agg(id::text,to_jsonb(e)), '{}'::jsonb)
    INTO old_exercises FROM public.exercises e;
  old_programmes := jsonb_build_object('programmes',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.programmes t),'programme_weeks',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.programme_weeks t),'training_days',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.training_days t),'session_blocks',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.session_blocks t),'saved_blocks',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.saved_blocks t),'saved_block_items',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.saved_block_items t),'athlete_overrides',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.athlete_overrides t),'cohort_overrides',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.cohort_overrides t));
  IF jsonb_array_length(inventory) <> 20 THEN RAISE EXCEPTION 'Expected exactly 20 mappings'; END IF;
  FOR row_data IN SELECT value FROM jsonb_array_elements(inventory) LOOP
    IF NOT EXISTS (SELECT 1 FROM public.exercise_categories WHERE slug=row_data->>'category_slug' AND active) THEN
      RAISE EXCEPTION 'Unknown category for %',row_data->>'code';
    END IF;
    SELECT count(*) INTO matched FROM public.exercises
      WHERE code=row_data->>'code' OR lower(name)=lower(row_data->>'name') OR video_id=row_data->>'video_id';
    IF matched > 0 THEN
      IF matched <> 1 THEN RAISE EXCEPTION 'Ambiguous existing mapping for %',row_data->>'code'; END IF;
      SELECT * INTO prior FROM public.exercises
        WHERE code=row_data->>'code' OR lower(name)=lower(row_data->>'name') OR video_id=row_data->>'video_id';
      IF prior.code IS DISTINCT FROM row_data->>'code'
        OR prior.name IS DISTINCT FROM row_data->>'name'
        OR prior.video_id IS DISTINCT FROM row_data->>'video_id'
        OR prior.video_url IS DISTINCT FROM row_data->>'video_url'
        OR prior.active IS DISTINCT FROM true THEN
        RAISE EXCEPTION 'Existing mapping conflict for %; manual review required',row_data->>'code';
      END IF;
      CONTINUE;
    END IF;
    INSERT INTO public.exercises(code,name,category_slug,categories,video_id,video_url,coaching_cues,display_order,active,admin_notes)
    VALUES(row_data->>'code',row_data->>'name',row_data->>'category_slug',
      ARRAY(SELECT jsonb_array_elements_text(row_data->'categories')),
      row_data->>'video_id',row_data->>'video_url',nullif(row_data->>'coaching_cues',''),
      (row_data->>'display_order')::integer,true,row_data->>'admin_notes');
  END LOOP;
  SELECT count(*) INTO matched FROM jsonb_array_elements(inventory) r
    JOIN public.exercises e ON e.code=r->>'code' AND e.name=r->>'name'
      AND e.video_id=r->>'video_id' AND e.video_url=r->>'video_url' AND e.active
      AND e.category_slug=r->>'category_slug'
      AND to_jsonb(e.categories)=r->'categories';
  IF matched <> 20 THEN RAISE EXCEPTION 'Exact active mapping verification failed: %/20',matched; END IF;
  IF EXISTS (SELECT 1 FROM public.exercises e
    WHERE old_exercises ? e.id::text AND old_exercises->e.id::text IS DISTINCT FROM to_jsonb(e))
    OR (SELECT count(*) FROM public.exercises e WHERE old_exercises ? e.id::text) <> (SELECT count(*) FROM jsonb_object_keys(old_exercises)) THEN
    RAISE EXCEPTION 'Pre-existing exercise changed';
  END IF;
  new_programmes := jsonb_build_object('programmes',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.programmes t),'programme_weeks',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.programme_weeks t),'training_days',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.training_days t),'session_blocks',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.session_blocks t),'saved_blocks',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.saved_blocks t),'saved_block_items',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.saved_block_items t),'athlete_overrides',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.athlete_overrides t),'cohort_overrides',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.cohort_overrides t));
  IF old_programmes IS DISTINCT FROM new_programmes THEN RAISE EXCEPTION 'Programme integrity check failed'; END IF;
END
$release$;
